using System;using System.Collections.Generic;using UnityEngine;
namespace Exoduser.UnityPort {
 // Exact renderer local-to-world geometry. Two-sided triangles also work with the camera inside a hollow tree.
 public sealed class A2RSightQuery {
  sealed class Node{public Bounds bounds;public int start,count;public Node left,right;}
  sealed class Data{public Vector3[] vertices,centers;public Vector2[] uv;public int[] triangles,order,material;public Node root;}
  sealed class TriangleComparer:IComparer<int>{public Data data;public int axis;public int Compare(int a,int b){return data.centers[a][axis].CompareTo(data.centers[b][axis]);}}
  readonly Dictionary<Mesh,Data> cache=new Dictionary<Mesh,Data>();readonly Dictionary<Texture,Texture2D> alpha=new Dictionary<Texture,Texture2D>();
  Data Read(Mesh mesh){Data d;if(cache.TryGetValue(mesh,out d))return d;if(!mesh.isReadable)return null;d=new Data{vertices=mesh.vertices,uv=mesh.uv,triangles=mesh.triangles};int count=d.triangles.Length/3;d.centers=new Vector3[count];d.order=new int[count];d.material=new int[count];for(int i=0;i<count;i++){d.order[i]=i;d.centers[i]=(d.vertices[d.triangles[i*3]]+d.vertices[d.triangles[i*3+1]]+d.vertices[d.triangles[i*3+2]])/3;}int at=0;for(int sub=0;sub<mesh.subMeshCount;sub++){int n=(int)mesh.GetIndexCount(sub)/3;for(int j=0;j<n&&at<count;j++)d.material[at++]=sub;}d.root=Build(d,0,count);cache[mesh]=d;return d;}
  Node Build(Data d,int start,int count){var bounds=new Bounds(d.vertices[d.triangles[d.order[start]*3]],Vector3.zero);for(int i=start;i<start+count;i++){int t=d.order[i]*3;for(int j=0;j<3;j++)bounds.Encapsulate(d.vertices[d.triangles[t+j]]);}var n=new Node{bounds=bounds,start=start,count=count};if(count>12){var size=bounds.size;int axis=size.x>size.y&&size.x>size.z?0:size.y>size.z?1:2;Array.Sort(d.order,start,count,new TriangleComparer{data=d,axis=axis});int half=count/2;n.left=Build(d,start,half);n.right=Build(d,start+half,count-half);n.count=0;}return n;}
  bool Opaque(Material m,Vector2 uv){if(m==null)return true;string key=m.HasProperty("_MainTex")?"_MainTex":m.HasProperty("_BaseMap")?"_BaseMap":null;var texture=key!=null?m.GetTexture(key):null;if(texture==null)return true;Texture2D sample;if(!alpha.TryGetValue(texture,out sample)){var rt=RenderTexture.GetTemporary(256,256,0,RenderTextureFormat.ARGB32);var old=RenderTexture.active;try{Graphics.Blit(texture,rt);RenderTexture.active=rt;sample=new Texture2D(256,256,TextureFormat.RGBA32,false);sample.ReadPixels(new Rect(0,0,256,256),0,0);sample.Apply();sample.wrapMode=texture.wrapMode;alpha[texture]=sample;}finally{RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);}}uv=Vector2.Scale(uv,m.GetTextureScale(key))+m.GetTextureOffset(key);return sample.GetPixelBilinear(uv.x,uv.y).a>=.12f;}
  bool Trace(Data d,Node n,Ray ray,float length,Material[] materials,out Vector3 point){point=Vector3.zero;float near;if(!n.bounds.IntersectRay(ray,out near)||near>=length)return false;if(n.left!=null)return Trace(d,n.left,ray,length,materials,out point)||Trace(d,n.right,ray,length,materials,out point);for(int i=n.start;i<n.start+n.count;i++){int tri=d.order[i],a=d.triangles[tri*3],b=d.triangles[tri*3+1],c=d.triangles[tri*3+2];var e1=d.vertices[b]-d.vertices[a];var e2=d.vertices[c]-d.vertices[a];var p=Vector3.Cross(ray.direction,e2);float det=Vector3.Dot(e1,p);if(Mathf.Abs(det)<.0000001f)continue;float inv=1/det;var v=ray.origin-d.vertices[a];float u=Vector3.Dot(v,p)*inv;if(u<0||u>1)continue;var q=Vector3.Cross(v,e1);float w=Vector3.Dot(ray.direction,q)*inv;if(w<0||u+w>1)continue;float t=Vector3.Dot(e2,q)*inv;if(t<=.00001f||t>=length-.0001f)continue;var uv=d.uv.Length==d.vertices.Length?d.uv[a]*(1-u-w)+d.uv[b]*u+d.uv[c]*w:Vector2.zero;int slot=d.material[tri];if(!Opaque(slot<materials.Length?materials[slot]:null,uv))continue;point=ray.GetPoint(t);return true;}return false;}
  public bool Hit(Renderer body,Vector3 camera,Vector3 target,out Vector3 hit){hit=Vector3.zero;if(body==null||!body.enabled||!body.gameObject.activeInHierarchy)return false;float near;var worldRay=new Ray(camera,target-camera);float length=Vector3.Distance(camera,target);if(!body.bounds.IntersectRay(worldRay,out near)||near>=length-.02f)return false;var f=body.GetComponent<MeshFilter>();if(f==null||f.sharedMesh==null)return false;var d=Read(f.sharedMesh);if(d==null)return false;var inv=body.worldToLocalMatrix;var origin=inv.MultiplyPoint3x4(camera);var end=inv.MultiplyPoint3x4(target);Vector3 local;if(!Trace(d,d.root,new Ray(origin,end-origin),Vector3.Distance(origin,end),body.sharedMaterials,out local))return false;hit=body.localToWorldMatrix.MultiplyPoint3x4(local);return true;}
  public void Dispose(){foreach(var t in alpha.Values)UnityEngine.Object.Destroy(t);cache.Clear();}
 }
}
